1. use std::process::ExitCode;
2. 
3. #[derive(Clone, Copy, Debug, Eq, PartialEq)]
4. pub(crate) enum CliExitCode {
5.     Success,
6.     Failure,
7.     /// Refused for a user-facing policy reason (e.g. mode guard); the
8.     /// command printed an explanatory message to stderr.
9.     Refused,
10.     /// Code review found issues; the calling agent should remediate and retry.
11.     ReviewIssues,
12.     DoctorFailures(usize),
13. }
14. 
15. impl From<CliExitCode> for ExitCode {
16.     fn from(code: CliExitCode) -> Self {
17.         match code {
18.             CliExitCode::Success => Self::SUCCESS,
19.             CliExitCode::Failure => Self::from(1),
20.             CliExitCode::Refused => Self::from(2),
21.             CliExitCode::ReviewIssues => Self::from(3),
22.             CliExitCode::DoctorFailures(count) => {
23.                 let capped = u8::try_from(count).unwrap_or(u8::MAX);
24.                 Self::from(capped)
25.             }
26.         }
27.     }
28. }
29. 
30. pub(crate) fn from_i32(code: i32) -> ExitCode {
31.     match u8::try_from(code) {
32.         Ok(code) => ExitCode::from(code),
33.         Err(_) => ExitCode::from(1),
34.     }
35. }
36.

